// 10 个 seed 影视 ID 列表（必须包含）
export const SEED_MEDIA_IDS = [
  'media-seed-01',
  'media-seed-02',
  'media-seed-03',
  'media-seed-04',
  'media-seed-05',
  'media-seed-06',
  'media-seed-07',
  'media-seed-08',
  'media-seed-09',
  'media-seed-10',
];

// 验证函数
export function validateMediaStoryMirrors(): {
  total: number;
  seedCount: number;
  allPublicReady: boolean;
  mediaTypes: string[];
  cultureRegionCount: number;
} {
  const seedIds = new Set(SEED_MEDIA_IDS);
  const seedCount = mediaStoryMirrors.filter(m => seedIds.has(m.id)).length;
  const allPublicReady = mediaStoryMirrors.every(m => m.review_status === 'public_ready');
  const types = new Set(mediaStoryMirrors.map(m => m.media_type));
  const cultures = new Set(mediaStoryMirrors.map(m => m.context_tags[0]));
  return {
    total: mediaStoryMirrors.length,
    seedCount,
    allPublicReady,
    mediaTypes: Array.from(types),
    cultureRegionCount: cultures.size,
  };
}